"""Section-span views of one original, certified whole-Street cubic.

Only scalar knot origins change. Original controls, tangents, coefficients and
the interpolation fallback remain those of the complete source. Knot indices
are private topology bindings rebuilt by managed topology edits, not source IDs.
These groups do not certify a junction footprint or generated surface.
"""
import bpy
from . import curved_corner_nodes as c

PREFIX = 'Prochitecture Streets / Original cubic span '


def view():
    """Take an inclusive knot range from an already oriented certified table.

    Path must come from curved_corner_nodes.prepare_path (or a table derived
    without changing its cubic coefficients), together with its Valid output.
    Final-row coefficients remain untouched; evaluation uses the last included
    interval for that endpoint, as for the complete original table.
    """
    name = PREFIX+'coefficient-preserving view v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Path', 'NodeSocketGeometry')
    g.socket('Source Valid', 'NodeSocketBool', default=False)
    for key in ('First Knot', 'Last Knot'):
        g.socket(key, 'NodeSocketInt')
    for key, kind in (('Geometry', 'NodeSocketGeometry'), ('Length', 'NodeSocketFloat'),
                      ('Origin', 'NodeSocketFloat'), ('Valid', 'NodeSocketBool')):
        g.socket(key, kind, 'OUTPUT')
    inp = g.node('NodeGroupInput'); path = inp.outputs['Path']
    first = c.V(g, inp.outputs['First Knot']); last = c.V(g, inp.outputs['Last Knot'])
    count = c._count(g, path); index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    origin = c._read(g, path, 'st_cc_knot', first)
    length = c._read(g, path, 'st_cc_knot', last)-origin
    valid = c.V(g, inp.outputs['Source Valid'])*g.math('GREATER_THAN', first, -.5)
    valid = valid*g.math('GREATER_THAN', last, first+.5)*g.math('LESS_THAN', last, count-.5)
    valid = valid*g.math('LESS_THAN', count, c.MAX_CONTROLS+.5)*g.math('GREATER_THAN', length, 1e-5)
    present = 1.
    for key, kind in (('knot', 'FLOAT'), ('span', 'FLOAT'), ('p', 'FLOAT_VECTOR'),
                      ('tangent', 'FLOAT_VECTOR'), ('a', 'FLOAT_VECTOR'),
                      ('b', 'FLOAT_VECTOR'), ('c', 'FLOAT_VECTOR')):
        attr = g.node('GeometryNodeInputNamedAttribute'); attr.data_type = kind
        attr.inputs['Name'].default_value = 'st_cc_'+key
        present = present*c.V(g, attr.outputs['Exists'])
    valid = valid*c._stat(g, path, present)
    selection = g.math('GREATER_THAN', index, first-.5)*g.math('LESS_THAN', index, last+.5)
    selected = c._select(g, path, selection)
    # Freeze the translated knot before positioning the scalar search mesh.
    selected = c._store(g, selected, 'st_cc_knot', c.named(g, 'st_cc_knot')-origin)
    selected = g.setpos(selected, g.xyz(c.named(g, 'st_cc_knot')))
    publish = g.node('GeometryNodeSwitch', 'Reject invalid ranges without clamping their identity')
    publish.input_type = 'GEOMETRY'; g.bind(valid, publish.inputs['Switch'])
    g.bind(selected, publish.inputs['True'])
    out = g.node('NodeGroupOutput'); g.bind(publish.outputs['Output'], out.inputs['Geometry'])
    for key, value in (('Length', c.choose(g, valid, length, 0.)),
                       ('Origin', c.choose(g, valid, origin, 0.)), ('Valid', valid)):
        g.bind(value, out.inputs[key])
    return g.g


def prepare(*, endpoint_tangents=False, interpolation=False, endpoint_frames=False):
    """Prepare the whole original curve, then select an authored control range.

    First/Last Control are always in authored order, even for Reverse=True.
    Width/Offset certify the complete source with the established guard. A
    variable-width source can supply its existing conservative width envelope;
    this does not itself declare or generate dimensional transitions.
    """
    if endpoint_frames and not interpolation:
        raise ValueError('Declared endpoint miters require mode-aware source preparation')
    name = PREFIX+'prepared source range v1'
    if endpoint_tangents:name+=' / Declared original endpoint tangents v1'
    if interpolation:name+=' / Exact or smooth v1'
    if endpoint_frames:name+=' / Declared endpoint miters v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Geometry', 'NodeSocketGeometry')
    g.socket('Reverse', 'NodeSocketBool', default=False)
    g.socket('Width', 'NodeSocketFloat', default=6.)
    g.socket('Offset', 'NodeSocketFloat', default=0.)
    if interpolation:g.socket('Interpolation','NodeSocketInt',default=3)
    if endpoint_tangents:
        for side in ('Start','End'):
            g.socket('Use '+side+' Tangent','NodeSocketBool',default=False)
            g.socket(side+' Tangent','NodeSocketVector')
    if endpoint_frames:
        for side in ('Start','End'):
            g.socket('Use '+side+' Profile Axis','NodeSocketBool',default=False)
            g.socket(side+' Profile Axis','NodeSocketVector')
    for key in ('First Control', 'Last Control'):
        g.socket(key, 'NodeSocketInt')
    for key, kind in (('Geometry', 'NodeSocketGeometry'), ('Whole Path', 'NodeSocketGeometry'),
                      ('Length', 'NodeSocketFloat'), ('Origin', 'NodeSocketFloat'),
                      ('Valid', 'NodeSocketBool'), ('Weighted', 'NodeSocketBool')):
        g.socket(key, kind, 'OUTPUT')
    inp = g.node('NodeGroupInput')
    whole = g.node('GeometryNodeGroup', 'Certify the complete original Street before selecting a span')
    whole.node_tree = c.prepare_path(endpoint_tangents=endpoint_tangents)
    for key in ('Geometry', 'Reverse', 'Width', 'Offset'):
        g.bind(inp.outputs[key], whole.inputs[key])
    if endpoint_tangents:
        # Public inputs are in original authored direction. Reverse only the
        # evaluated view, including which end and tangent it starts with.
        reverse=inp.outputs['Reverse']
        for side,peer in (('Start','End'),('End','Start')):
            g.bind(c.choose(g,reverse,inp.outputs['Use '+peer+' Tangent'],inp.outputs['Use '+side+' Tangent'],'BOOLEAN'),
                   whole.inputs['Use '+side+' Tangent'])
            vector=c._pick(g,reverse,c._scale(c._vec(g,inp.outputs[peer+' Tangent']),-1.),
                           c._vec(g,inp.outputs[side+' Tangent']))
            g.bind(g.xyz(*vector),whole.inputs[side+' Tangent'])
    if interpolation:
        from . import curved_exact_path_nodes
        exact=g.node('GeometryNodeGroup','Preserve authored polyline bends and offset-line corners')
        exact.node_tree=curved_exact_path_nodes.prepare(endpoint_tangents=endpoint_tangents,endpoint_frames=endpoint_frames)
        # Copy input wiring, including the authored-to-outward tangent mapping.
        for socket in whole.inputs:
            if not socket.enabled:continue
            target=exact.inputs.get(socket.name)
            if target is None:continue
            if socket.is_linked:g.bind(socket.links[0].from_socket,target)
            elif hasattr(socket,'default_value'):target.default_value=socket.default_value
        if endpoint_frames:
            reverse=inp.outputs['Reverse']
            for side,peer in (('Start','End'),('End','Start')):
                enabled=c.choose(g,reverse,inp.outputs['Use '+peer+' Profile Axis'],inp.outputs['Use '+side+' Profile Axis'],'BOOLEAN')
                axis=c._pick(g,reverse,c._scale(c._vec(g,inp.outputs[peer+' Profile Axis']),-1.),
                             c._vec(g,inp.outputs[side+' Profile Axis']))
                # Preserve the authored Z component so the Exact primitive
                # can reject nonplanar input rather than silently dropping it.
                z=c.choose(g,reverse,-g.separate(inp.outputs[peer+' Profile Axis'])[2],
                           g.separate(inp.outputs[side+' Profile Axis'])[2])
                g.bind(enabled,exact.inputs['Use '+side+' Profile Axis'])
                g.bind(g.xyz(*axis,z),exact.inputs[side+' Profile Axis'])
        mode=c.V(g,inp.outputs['Interpolation'])
        valid_mode=g.math('MAXIMUM',g.math('COMPARE',mode,0.),g.math('COMPARE',mode,3.))
        if endpoint_frames:
            enabled=g.math('MAXIMUM',inp.outputs['Use Start Profile Axis'],inp.outputs['Use End Profile Axis'])
            valid_mode=valid_mode*c.choose(g,enabled,g.math('COMPARE',mode,0.),1.)
        outputs={key:c.choose(g,g.math('COMPARE',mode,0.),exact.outputs[key],whole.outputs[key],kind)
                 for key,kind in (('Geometry','GEOMETRY'),('Valid','BOOLEAN'),('Weighted','BOOLEAN'))}
    else:outputs={key:c.V(g,whole.outputs[key]) for key in ('Geometry','Valid','Weighted')}
    size = c._count(g, inp.outputs['Geometry'])
    first, last = (c.V(g, inp.outputs[key]) for key in ('First Control', 'Last Control'))
    selected = g.node('GeometryNodeGroup', 'Retain original cubic coefficients and endpoint tangents')
    selected.node_tree = view()
    g.bind(outputs['Geometry'], selected.inputs['Path'])
    # The original table's curvature guard alone does not reject negative width.
    width = c.V(g, inp.outputs['Width']); offset = c.V(g, inp.outputs['Offset'])
    valid = outputs['Valid']*g.math('GREATER_THAN', width, 1e-5)
    if interpolation:valid=valid*valid_mode
    valid = valid*g.math('LESS_THAN', width, 1e5)*g.math('LESS_THAN', g.math('ABSOLUTE', offset), 1e5)
    g.bind(valid, selected.inputs['Source Valid'])
    g.bind(c.choose(g, inp.outputs['Reverse'], size-1.-last, first, 'INT'), selected.inputs['First Knot'])
    g.bind(c.choose(g, inp.outputs['Reverse'], size-1.-first, last, 'INT'), selected.inputs['Last Knot'])
    out = g.node('NodeGroupOutput')
    for key in ('Geometry', 'Length', 'Origin', 'Valid'):
        g.bind(selected.outputs[key], out.inputs[key])
    g.bind(outputs['Geometry'], out.inputs['Whole Path'])
    g.bind(outputs['Weighted'], out.inputs['Weighted'])
    return g.g
